export const k8sUpdateCommand = defineCommand({
  description: 'Update the settings of a Kubernetes cluster',
  since: null,
  options: {
    name: defineOption({
      name: 'name',
      schema: z.string().trim().min(1).optional(),
      description: 'New cluster name',
      placeholder: 'name',
    }),
    description: defineOption({
      name: 'description',
      schema: z.string().max(4096).optional(),
      description: 'Free-form cluster description',
      placeholder: 'description',
    }),
    tag: defineOption({
      name: 'tag',
      schema: z.string().transform(tags).optional(),
      description: 'Semantic tags, replacing the current ones (comma-separated, e.g.: env:prod,team:platform)',
      placeholder: 'tag[,tag...]',
    }),
    autoscaling: defineOption({
      name: 'autoscaling',
      schema: z.enum(['enabled', 'disabled']).optional(),
      description: 'Enable or disable the cluster autoscaler',
      placeholder: 'enabled|disabled',
      complete: () => ['enabled', 'disabled'],
    }),
    org: orgaIdOrNameOption,
    format: humanJsonOutputFormatOption,
  },
  args: [k8sIdOrNameArg],
  async handler(options, clusterIdOrName) {
    const { name, description, tag, autoscaling, org: orgIdOrName, format } = options;

    const updates = {};
    if (name != null) updates.name = name;
    if (description != null) updates.description = description;
    if (tag != null) updates.tags = tag;
    if (autoscaling != null) updates.features = { autoscalingEnabled: autoscaling === 'enabled' };

    if (Object.keys(updates).length === 0) {
      throw new Error('Nothing to update, use at least one of --name, --description, --tag or --autoscaling');
    }

    const cluster = await k8sUpdate(orgIdOrName, clusterIdOrName, updates);

    switch (format) {
      case 'json': {
        Logger.printJson(cluster);
        break;
      }
      case 'human':
      default: {
        Logger.printSuccess(`Kubernetes cluster ${styleText('green', `${cluster.name} (${cluster.id})`)} updated`);
